// OBS Baseball Graphics: After Effects template builder.
// Generated by the Adobe templates page (control panel > Adobe). Run it in After Effects:
// File > Scripts > Run Script File... and pick this file (keep the "images" folder next to it).
// It builds one composition per graphic with the editable fields already in the Essential Graphics
// panel, then (optionally) saves every composition as a Motion Graphics template (.mogrt) for Premiere Pro.
// Needs After Effects CC 2019 (16.1) or later. Written in ExtendScript (ES3): no let, const or arrow functions.
// BBG_DATA is defined above this line by the page that generated the script.

(function (D) {
    var FPS = D.fps || 30;
    var HERE = (new File($.fileName)).parent;
    var LOG = [];

    function log(s) { LOG.push(s); }
    var FONTS_MISSING = {};
    function noteFont(want, used) {
        if (FONTS_MISSING[want]) return;
        FONTS_MISSING[want] = true;
        log("Font " + want + " is not installed; used " + used + ". Install it and change the font in the template if you want an exact match.");
    }

    // ---- small helpers --------------------------------------------------------------
    function prop(group, names) {
        // First property found by match name or display name (match names work in every language of AE).
        for (var i = 0; i < names.length; i++) {
            try {
                var p = group.property(names[i]);
                if (p) return p;
            } catch (e) {}
        }
        return null;
    }
    function tr(layer, which) {
        var g = layer.property("ADBE Transform Group");
        return prop(g, { anchor: ["ADBE Anchor Point", "Anchor Point"], pos: ["ADBE Position", "Position"], scale: ["ADBE Scale", "Scale"],
                         rot: ["ADBE Rotate Z", "Rotation"], opacity: ["ADBE Opacity", "Opacity"] }[which]);
    }
    function effect(layer, matchName) {
        var fx = layer.property("ADBE Effect Parade");
        return fx.addProperty(matchName);
    }
    function fxProp(fx, idx, name) {
        return prop(fx, [fx.matchName + "-" + (idx < 10 ? "000" : "00") + idx, name]);
    }
    function rgb(c) { return [c[0], c[1], c[2]]; }
    function setEase(p, key, inf) {
        // Different property types want 1, 2 or 3 ease objects: try until one fits.
        var e = new KeyframeEase(0, inf);
        var tries = [[e], [e, e], [e, e, e]];
        for (var i = 0; i < tries.length; i++) {
            try { p.setTemporalEaseAtKey(key, tries[i], tries[i]); return; } catch (err) {}
        }
    }
    function keys(p, list, easeOut) {
        // list: [[time, value], ...]
        if (!p || !list || !list.length) return;
        for (var i = 0; i < list.length; i++) {
            try { p.setValueAtTime(list[i][0], list[i][1]); } catch (e) { log("key: " + e.toString()); }
        }
        for (var k = 1; k <= p.numKeys; k++) setEase(p, k, easeOut ? 70 : 40);
    }
    function addToEG(p, comp, name) {
        if (!p) return;
        try {
            if (p.canAddToMotionGraphicsTemplate(comp)) p.addToMotionGraphicsTemplateAs(comp, name);
        } catch (e) { log("Essential Graphics: " + name + ": " + e.toString()); }
    }
    function roundRect(w, h, r) {
        var s = new Shape();
        r = Math.max(0, Math.min(r || 0, w / 2, h / 2));
        if (!r) {
            s.vertices = [[0, 0], [w, 0], [w, h], [0, h]];
            s.closed = true;
            return s;
        }
        var k = r * 0.5523;
        s.vertices = [[r, 0], [w - r, 0], [w, r], [w, h - r], [w - r, h], [r, h], [0, h - r], [0, r]];
        s.inTangents = [[-k, 0], [0, 0], [0, -k], [0, 0], [k, 0], [0, 0], [0, k], [0, 0]];
        s.outTangents = [[0, 0], [k, 0], [0, 0], [0, k], [0, 0], [-k, 0], [0, 0], [0, -k]];
        s.closed = true;
        return s;
    }
    function ellipse(w, h) {
        var s = new Shape(), kx = w / 2 * 0.5523, ky = h / 2 * 0.5523;
        s.vertices = [[w / 2, 0], [w, h / 2], [w / 2, h], [0, h / 2]];
        s.inTangents = [[-kx, 0], [0, -ky], [kx, 0], [0, ky]];
        s.outTangents = [[kx, 0], [0, ky], [-kx, 0], [0, -ky]];
        s.closed = true;
        return s;
    }
    function addMask(layer, shape, name) {
        var m = layer.property("ADBE Mask Parade").addProperty("ADBE Mask Atom");
        m.name = name || "Shape";
        prop(m, ["ADBE Mask Shape", "Mask Path"]).setValue(shape);
        return m;
    }
    function teamExpr(team, mode) {
        // mode: "flat", "light" (top of a gradient) or "dark" (bottom of a gradient)
        var c = 'thisComp.layer("Controls").effect("' + team.label + '")(1)';
        if (mode === "light") return "c=" + c + "; [c[0]+(1-c[0])*0.18, c[1]+(1-c[1])*0.18, c[2]+(1-c[2])*0.18, 1]";
        if (mode === "dark") return "c=" + c + "; [c[0]*0.68, c[1]*0.68, c[2]*0.68, 1]";
        return c;
    }
    function shadow(layer, sh) {
        if (!sh) return;
        try {
            var fx = effect(layer, "ADBE Drop Shadow");
            fxProp(fx, 1, "Shadow Color").setValue(rgb(sh.color));
            var op = fxProp(fx, 2, "Opacity");
            try { op.setValue(Math.round(sh.color[3] * 255)); } catch (e1) { op.setValue(Math.round(sh.color[3] * 100)); }
            fxProp(fx, 3, "Direction").setValue(sh.dir);
            fxProp(fx, 4, "Distance").setValue(sh.dist);
            fxProp(fx, 5, "Softness").setValue(sh.blur);
        } catch (e) { log("shadow: " + e.toString()); }
    }

    // ---- animation ---------------------------------------------------------------------
    function animate(layer, a, base) {
        if (!a) return;
        if (a.o) keys(tr(layer, "opacity"), a.o, true);
        if (a.p) {
            var pk = [];
            for (var i = 0; i < a.p.length; i++) pk.push([a.p[i][0], [base[0] + a.p[i][1][0], base[1] + a.p[i][1][1]]]);
            keys(tr(layer, "pos"), pk, true);
        }
        if (a.s) {
            var sk = [];
            for (var j = 0; j < a.s.length; j++) sk.push([a.s[j][0], [a.s[j][1][0], a.s[j][1][1], 100]]);
            keys(tr(layer, "scale"), sk, true);
        }
        if (a.w) {
            try {
                var fx = effect(layer, "ADBE Linear Wipe");
                fxProp(fx, 2, "Wipe Angle").setValue(a.w.angle);
                fxProp(fx, 3, "Feather").setValue(0);
                keys(fxProp(fx, 1, "Transition Completion"), a.w.k, true);
            } catch (e) { log("wipe: " + e.toString()); }
        }
    }

    // ---- layer builders ----------------------------------------------------------------
    function makeBox(comp, L) {
        var w = Math.max(1, Math.round(L.w)), h = Math.max(1, Math.round(L.h));
        var c0 = L.fill ? L.fill.c0 : [0, 0, 0, 1];
        var layer = comp.layers.addSolid(rgb(c0), L.name, w, h, 1);
        var pos = [L.x + L.w / 2, L.y + L.h / 2];
        tr(layer, "pos").setValue(pos);
        if (L.rot) tr(layer, "rot").setValue(L.rot);
        if (L.round === "ellipse") addMask(layer, ellipse(w, h));
        else if (L.r) addMask(layer, roundRect(w, h, L.r));
        var f = L.fill;
        if (f && f.kind === "ramp") {
            var fx = effect(layer, "ADBE Ramp");
            fxProp(fx, 1, "Start of Ramp").setValue([f.p0[0] * w, f.p0[1] * h]);
            fxProp(fx, 3, "End of Ramp").setValue([f.p1[0] * w, f.p1[1] * h]);
            var sc = fxProp(fx, 2, "Start Color"), ec = fxProp(fx, 4, "End Color");
            sc.setValue(rgb(f.c0));
            ec.setValue(rgb(f.c1));
            if (f.radial) fxProp(fx, 5, "Ramp Shape").setValue(2);
            if (L.team) { sc.expression = teamExpr(L.team, "light"); ec.expression = teamExpr(L.team, "dark"); }
        } else if (L.team) {
            var fl = effect(layer, "ADBE Fill");
            fxProp(fl, 2, "Color").expression = teamExpr(L.team, "flat");
        }
        if (L.alpha != null && L.alpha < 1) tr(layer, "opacity").setValue(Math.round(L.alpha * 100));
        shadow(layer, L.shadow);
        animate(layer, L.anim, pos);
        if (L.border) makeBorder(comp, L, pos);
        return layer;
    }
    function makeBorder(comp, L, pos) {
        var layer = comp.layers.addShape();
        layer.name = L.name + " border";
        var grp = layer.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
        var vecs = grp.property("ADBE Vectors Group");
        var shapeType = L.round === "ellipse" ? "ADBE Vector Shape - Ellipse" : "ADBE Vector Shape - Rect";
        var rect = vecs.addProperty(shapeType);
        var bw = L.border.w;
        prop(rect, [shapeType === "ADBE Vector Shape - Rect" ? "ADBE Vector Rect Size" : "ADBE Vector Ellipse Size", "Size"]).setValue([L.w - bw, L.h - bw]);
        if (shapeType === "ADBE Vector Shape - Rect" && L.r) prop(rect, ["ADBE Vector Rect Roundness", "Roundness"]).setValue(Math.max(0, L.r - bw / 2));
        var st = vecs.addProperty("ADBE Vector Graphic - Stroke");
        prop(st, ["ADBE Vector Stroke Color", "Color"]).setValue(rgb(L.border.c));
        prop(st, ["ADBE Vector Stroke Width", "Stroke Width"]).setValue(bw);
        tr(layer, "pos").setValue(pos);
        if (L.rot) tr(layer, "rot").setValue(L.rot);
        if (L.border.c[3] < 1) tr(layer, "opacity").setValue(Math.round(L.border.c[3] * 100));
        animate(layer, L.anim, pos);
    }
    function fontExists(name) {
        // After Effects 24 and later can look a font up; older versions are checked after setting it.
        try {
            if (app.fonts && app.fonts.getFontsByPostScriptName) return app.fonts.getFontsByPostScriptName(name).length > 0;
        } catch (e) {}
        return null;
    }
    function setFont(srcProp, td, list) {
        for (var i = 0; i < list.length; i++) {
            var ok = fontExists(list[i]);
            if (ok === false) continue;
            try {
                td.font = list[i];
                srcProp.setValue(td);
                if (ok === true || srcProp.value.font === list[i]) return list[i];
            } catch (e) {}
        }
        return srcProp.value.font;
    }
    function makeText(comp, L, controls) {
        var layer = L.wrap ? comp.layers.addBoxText([Math.max(10, L.w), Math.max(10, L.h)], L.text) : comp.layers.addText(L.text);
        layer.name = L.name;
        var srcProp = layer.property("ADBE Text Properties").property("ADBE Text Document");
        var td = srcProp.value;
        td.resetCharStyle();
        td.text = L.text;
        td.fontSize = L.size;
        srcProp.setValue(td);
        var used = setFont(srcProp, td, L.fonts);
        if (used !== L.fonts[0]) noteFont(L.fonts[0], used);
        td = srcProp.value;
        td.applyFill = true;
        td.fillColor = rgb(L.color);
        td.tracking = L.tracking || 0;
        if (L.stroke) {
            td.applyStroke = true;
            td.strokeColor = rgb(L.stroke.c);
            td.strokeWidth = L.stroke.w;
            td.strokeOverFill = false;
        } else td.applyStroke = false;
        td.justification = L.align === "center" ? ParagraphJustification.CENTER_JUSTIFY :
                           (L.align === "right" ? ParagraphJustification.RIGHT_JUSTIFY : ParagraphJustification.LEFT_JUSTIFY);
        srcProp.setValue(td);
        var k = L.align === "center" ? 0.5 : (L.align === "right" ? 1 : 0);
        var pos;
        if (L.wrap) {
            pos = [L.x + L.w / 2, L.y + L.h / 2];
            tr(layer, "anchor").expression = "r=sourceRectAtTime(time,false); [r.left+r.width/2, r.top+r.height/2]";
            tr(layer, "pos").setValue(pos);
        } else {
            // Anchored at its alignment edge and vertical centre, so edits in Premiere stay in place,
            // and it shrinks to fit its box like the live graphic does.
            pos = [L.ax, L.cy];
            tr(layer, "anchor").expression = "r=sourceRectAtTime(time,false); [r.left+r.width*" + k + ", r.top+r.height/2]";
            tr(layer, "pos").setValue(pos);
            if (L.maxW) tr(layer, "scale").expression = "w=sourceRectAtTime(time,false).width; s=(w>" + L.maxW + ")?100*" + L.maxW + "/w:100; [s,s]";
        }
        if (L.rot) tr(layer, "rot").setValue(L.rot);
        if (L.alpha != null && L.alpha < 1) tr(layer, "opacity").setValue(Math.round(L.alpha * 100));
        if (L.team) {
            var fl = effect(layer, "ADBE Fill");
            fxProp(fl, 2, "Color").expression = teamExpr(L.team, "flat");
        }
        shadow(layer, L.shadow);
        animate(layer, L.anim, pos);
        if (L.edit) addToEG(srcProp, comp, L.edit);
        return layer;
    }
    function makeImage(comp, L) {
        var item = null;
        if (L.file) {
            var f = new File(HERE.fsName + "/images/" + L.file);
            if (f.exists) {
                try { item = app.project.importFile(new ImportOptions(f)); item.parentFolder = imgFolder(); } catch (e) { log("import " + L.file + ": " + e.toString()); }
            }
        }
        var layer, pos = [L.x + L.w / 2, L.y + L.h / 2];
        if (!item) {
            // No picture: a gray stand-in to replace (right-click > Replace Footage, or Media Replacement in Premiere).
            layer = comp.layers.addSolid([0.5, 0.52, 0.56], L.name + " (replace)", Math.max(1, Math.round(L.w)), Math.max(1, Math.round(L.h)), 1);
            tr(layer, "pos").setValue(pos);
            tr(layer, "opacity").setValue(35);
        } else {
            layer = comp.layers.add(item);
            layer.name = L.name;
            var sx = L.w / item.width, sy = L.h / item.height;
            var s = L.fit === "cover" ? Math.max(sx, sy) : Math.min(sx, sy);
            tr(layer, "scale").setValue([s * 100, s * 100]);
            tr(layer, "pos").setValue(pos);
            if (L.fit === "cover") {
                // Crop to the box, in the picture's own pixels.
                var vw = L.w / s, vh = L.h / s;
                var ox = (item.width - vw) / 2, oy = L.focusTop ? 0 : (item.height - vh) / 2;
                var sh = roundRect(vw, vh, (L.r || 0) / s);
                var v = sh.vertices;
                for (var i = 0; i < v.length; i++) v[i] = [v[i][0] + ox, v[i][1] + oy];
                sh.vertices = v;
                addMask(layer, sh);
                if (L.focusTop) tr(layer, "pos").setValue([pos[0], L.y + item.height * s / 2]);
                if (L.focusTop) pos = [pos[0], L.y + item.height * s / 2];
            }
        }
        if (L.rot) tr(layer, "rot").setValue(L.rot);
        if (L.alpha != null && L.alpha < 1) tr(layer, "opacity").setValue(Math.round(L.alpha * 100));
        animate(layer, L.anim, pos);
        return layer;
    }
    function makeBase(comp, L) {
        // A base bag that lights up when its checkbox on the Controls layer is ticked.
        var w = Math.max(2, Math.round(L.w));
        var layer = comp.layers.addSolid(rgb(L.on), L.name, w, w, 1);
        var pos = [L.x + L.w / 2, L.y + L.h / 2];
        tr(layer, "pos").setValue(pos);
        tr(layer, "rot").setValue(45);
        var fl = effect(layer, "ADBE Fill");
        fxProp(fl, 2, "Color").expression = 'thisComp.layer("Controls").effect("' + L.ctl + '")(1)==1 ? [' + L.on.join(",") + '] : [' + L.off.join(",") + ']';
        tr(layer, "opacity").expression = 'thisComp.layer("Controls").effect("' + L.ctl + '")(1)==1 ? ' + Math.round(L.on[3] * 100) + " : " + Math.round(L.off[3] * 100);
        if (L.border) makeBorder(comp, { name: L.name, w: w, h: w, r: 0, rot: 45, border: L.border, anim: L.anim }, pos);
        animate(layer, L.anim, pos);
        return layer;
    }
    function makeDot(comp, L) {
        var w = Math.max(2, Math.round(L.w));
        var layer = comp.layers.addSolid(rgb(L.on), L.name, w, w, 1);
        var pos = [L.x + L.w / 2, L.y + L.h / 2];
        tr(layer, "pos").setValue(pos);
        if (L.round) addMask(layer, ellipse(w, w));
        var fl = effect(layer, "ADBE Fill");
        fxProp(fl, 2, "Color").expression = 'thisComp.layer("Controls").effect("' + L.ctl + '")(1)>=' + L.n + ' ? [' + L.on.join(",") + '] : [' + L.off.join(",") + ']';
        tr(layer, "opacity").expression = 'thisComp.layer("Controls").effect("' + L.ctl + '")(1)>=' + L.n + ' ? ' + Math.round(L.on[3] * 100) + " : " + Math.round(L.off[3] * 100);
        animate(layer, L.anim, pos);
        return layer;
    }

    // ---- project folders -------------------------------------------------------------
    var ROOT = null, IMG = null;
    function rootFolder() {
        if (!ROOT) ROOT = app.project.items.addFolder(D.title);
        return ROOT;
    }
    function imgFolder() {
        if (!IMG) { IMG = app.project.items.addFolder("Images"); IMG.parentFolder = rootFolder(); }
        return IMG;
    }

    // ---- one composition per graphic ---------------------------------------------------
    function build(G) {
        var comp = app.project.items.addComp(G.name, 1920, 1080, 1, G.duration, FPS);
        comp.parentFolder = rootFolder();
        comp.bgColor = [0, 0, 0];
        for (var i = 0; i < G.layers.length; i++) {
            var L = G.layers[i];
            try {
                if (L.t === "box") makeBox(comp, L);
                else if (L.t === "text") makeText(comp, L);
                else if (L.t === "image") makeImage(comp, L);
                else if (L.t === "base") makeBase(comp, L);
                else if (L.t === "dot") makeDot(comp, L);
            } catch (e) { log(G.name + " / " + L.name + ": " + e.toString()); }
        }
        // Controls: team colours, runners, outs. Each one is in the Essential Graphics panel.
        if (G.controls && G.controls.length) {
            var ctl = comp.layers.addNull();
            ctl.name = "Controls";
            ctl.guideLayer = true;
            ctl.enabled = false;
            for (var c = 0; c < G.controls.length; c++) {
                var C = G.controls[c];
                try {
                    var fx = effect(ctl, C.kind === "color" ? "ADBE Color Control" : (C.kind === "check" ? "ADBE Checkbox Control" : "ADBE Slider Control"));
                    fx.name = C.label;
                    var p = fx.property(1);
                    p.setValue(C.kind === "color" ? rgb(C.value) : C.value);
                    addToEG(p, comp, C.label);
                } catch (e2) { log(G.name + " / control " + C.label + ": " + e2.toString()); }
            }
        }
        // Text fields come after the colours in the panel order Premiere shows.
        // Protected regions: Premiere keeps the in and out animations at their speed when the clip is stretched.
        try {
            var mi = new MarkerValue("In");
            mi.duration = G.inEnd;
            mi.protectedRegion = true;
            comp.markerProperty.setValueAtTime(0, mi);
            var mo = new MarkerValue("Out");
            mo.duration = G.duration - G.outStart;
            mo.protectedRegion = true;
            comp.markerProperty.setValueAtTime(G.outStart, mo);
        } catch (e3) { log(G.name + " markers: " + e3.toString()); }
        try { comp.motionGraphicsTemplateName = G.name; } catch (e4) {}
        return comp;
    }

    app.beginUndoGroup("OBS Baseball Graphics templates");
    var comps = [];
    for (var g = 0; g < D.graphics.length; g++) comps.push(build(D.graphics[g]));
    app.endUndoGroup();

    var msg = "Built " + comps.length + " composition(s) in the folder \"" + D.title + "\".";
    if (comps.length && confirm(msg + "\n\nSave each one as a Motion Graphics template (.mogrt) for Premiere Pro now?")) {
        var out = Folder.selectDialog("Pick a folder for the .mogrt files");
        if (out) {
            for (var m = 0; m < comps.length; m++) {
                var safe = comps[m].name.replace(/[\\\/:*?"<>|]/g, "-");
                try { comps[m].exportAsMotionGraphicsTemplate(true, out.fsName + "/" + safe + ".mogrt"); } catch (e5) { log("export " + safe + ": " + e5.toString()); }
            }
            msg += "\nSaved .mogrt files to " + out.fsName + ".";
        }
    }
    if (LOG.length) msg += "\n\nNotes (" + LOG.length + "):\n" + LOG.slice(0, 15).join("\n") + (LOG.length > 15 ? "\n..." : "");
    alert(msg);
})(BBG_DATA);
